INSERT INTO vm_agent_operation_task_execution (
    task_id,user_id,task_execution_type, execution_status, start_time, end_time, error_message,
    execution_log, creator, modifier, create_time, update_time,group_id
) VALUES (
             #{taskId},#{userId},#{taskExecutionType}, #{executionStatus}, #{startTime}, #{endTime}, #{errorMessage},
             #{executionLog}, #{creator}, #{modifier}, #{createTime}, #{updateTime}, #{groupId}
         )

mapper.update:
update vm_agent_operation_task_execution
set execution_status = #{executionStatus}

    ,end_time = #{endTime}


    ,execution_log = #{executionLog}


    ,error_message = #{errorMessage}


    ,ai_judge_total = #{aiJudgeTotal}


    ,real_num = #{realNum}


    ,false_num = #{falseNum}


    ,un_judged_num = #{unJudgedNum}


    ,update_time = #{updateTime}

where execution_id = #{executionId}
  AND delete_flag = 0

mapper.select:
SELECT a.* from (SELECT

,ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY create_time DESC) as rn
FROM vm_agent_operation_task_execution
WHERE user_id in

    #{userId}


    and task_execution_type = #{taskExecutionType}

AND execution_status = #{executionStatus}
AND delete_flag = 0
ORDER BY create_time DESC ) a WHERE a.rn = 1
